/* ============================================================
   MedBook — Corporate Landing Page Styles
   ============================================================ */

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #1B1464;
  --navy-light: #2a1f8e;
  --accent: #FFD930;
  --accent-hover: #f0cb00;
  --white: #FFFFFF;
  --gray-50: #F8F9FC;
  --gray-100: #F0F2F7;
  --gray-200: #E2E5EE;
  --gray-300: #C8CDD9;
  --gray-400: #9BA3B5;
  --gray-500: #6B7280;
  --gray-700: #374151;
  --gray-900: #111827;
  --teal: #0EA5A0;
  --teal-light: #14C8C1;
  --blue: #0066FF;
  --green: #10B981;
  --shadow-sm: 0 1px 3px rgba(27, 20, 100, 0.06);
  --shadow-md: 0 4px 14px rgba(27, 20, 100, 0.08);
  --shadow-lg: 0 10px 30px rgba(27, 20, 100, 0.12);
  --shadow-xl: 0 20px 50px rgba(27, 20, 100, 0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: 0.2s ease;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-700);
  background: var(--white);
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition);
}

ul, ol { list-style: none; }

img { max-width: 100%; display: block; }

button, input, select {
  font-family: inherit;
  font-size: inherit;
  border: none;
  outline: none;
  background: none;
}

button { cursor: pointer; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Typography --- */
h1, h2, h3, h4 {
  color: var(--navy);
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.25rem); }
h3 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 12px;
}

.section-title {
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--gray-500);
  max-width: 600px;
  margin: 0 auto 48px;
}

.text-center { text-align: center; }

/* ============================================================
   HEADER
   ============================================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--navy);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.1rem;
  font-weight: 900;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-desktop a {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-500);
  transition: color var(--transition);
}

.nav-desktop a:hover {
  color: var(--navy);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-login {
  padding: 8px 20px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--navy);
  border-radius: var(--radius-full);
  transition: background var(--transition);
}

.btn-login:hover {
  background: var(--gray-100);
}

.btn-signup {
  padding: 8px 20px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--white);
  background: var(--navy);
  border-radius: var(--radius-full);
  transition: background var(--transition), transform var(--transition);
}

.btn-signup:hover {
  background: var(--navy-light);
  transform: translateY(-1px);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  cursor: pointer;
  z-index: 1100;
}

.hamburger span {
  display: block;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 0.3s ease;
  transform-origin: center;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7.5px) rotate(45deg);
}
.hamburger.active span:nth-child(2) {
  opacity: 0;
}
.hamburger.active span:nth-child(3) {
  transform: translateY(-7.5px) rotate(-45deg);
}

/* Mobile drawer */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 1050;
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
  transition: right 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-drawer.open {
  right: 0;
}

.mobile-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(27, 20, 100, 0.3);
  z-index: 1040;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-drawer-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-drawer a {
  display: block;
  padding: 16px 0;
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--navy);
  border-bottom: 1px solid var(--gray-100);
}

.mobile-drawer a:last-child {
  border-bottom: none;
}

.mobile-drawer .btn-signup-mobile {
  display: block;
  text-align: center;
  margin-top: 24px;
  padding: 14px;
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(170deg, #F0EDFF 0%, var(--white) 60%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -200px;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 48, 0.15), transparent 70%);
  pointer-events: none;
}

.hero-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(27, 20, 100, 0.06);
  padding: 6px 16px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 24px;
}

.hero-badge-dot {
  width: 8px;
  height: 8px;
  background: var(--green);
  border-radius: 50%;
  animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.3); }
}

.hero h1 {
  margin-bottom: 20px;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--navy), #4338CA);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--gray-500);
  max-width: 560px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

/* ============================================================
   SEARCH BAR
   ============================================================ */
.search-container {
  max-width: 820px;
  margin: 0 auto;
}

.search-bar {
  display: flex;
  align-items: center;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 2px solid var(--gray-200);
  padding: 6px;
  transition: border-color var(--transition), box-shadow var(--transition);
  position: relative;
}

.search-bar:focus-within {
  border-color: var(--navy);
  box-shadow: var(--shadow-xl), 0 0 0 4px rgba(27, 20, 100, 0.08);
}

.search-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  min-width: 0;
  position: relative;
}

.search-field:not(:last-of-type)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 8px;
  bottom: 8px;
  width: 1px;
  background: var(--gray-200);
}

.search-field svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--gray-400);
}

.search-field input,
.search-field select {
  width: 100%;
  padding: 4px 0;
  font-size: 0.95rem;
  color: var(--gray-900);
  background: transparent;
}

.search-field input::placeholder,
.search-field select {
  color: var(--gray-400);
}

.search-field select option {
  color: var(--gray-700);
}

.search-btn {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  background: var(--accent);
  color: var(--navy);
  font-weight: 700;
  font-size: 1rem;
  border-radius: var(--radius-md);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.search-btn:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(255, 217, 48, 0.4);
}

.search-btn svg {
  width: 18px;
  height: 18px;
}

/* Autocomplete dropdown */
.autocomplete-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  max-height: 320px;
  overflow-y: auto;
  z-index: 100;
  display: none;
}

.autocomplete-dropdown.active {
  display: block;
  animation: dropdown-in 0.2s ease;
}

@keyframes dropdown-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.autocomplete-group-label {
  padding: 12px 16px 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-400);
}

.autocomplete-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: background var(--transition);
}

.autocomplete-item:hover,
.autocomplete-item.highlighted {
  background: var(--gray-50);
}

.autocomplete-item-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.autocomplete-item-text strong {
  display: block;
  font-size: 0.95rem;
  color: var(--gray-900);
}

.autocomplete-item-text span {
  font-size: 0.82rem;
  color: var(--gray-400);
}

/* Search popular tags below bar */
.search-popular {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

.search-popular-label {
  font-size: 0.85rem;
  color: var(--gray-400);
  font-weight: 500;
}

.search-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  background: rgba(27, 20, 100, 0.05);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--navy);
  transition: background var(--transition);
  cursor: pointer;
}

.search-tag:hover {
  background: rgba(27, 20, 100, 0.1);
}

/* ============================================================
   PLATFORM STATS
   ============================================================ */
.stats {
  padding: 40px 0;
}

.stats-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 28px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: transform var(--transition), box-shadow var(--transition);
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.stat-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}

.stat-icon.reviews { background: rgba(14, 165, 160, 0.1); color: var(--teal); }
.stat-icon.providers { background: rgba(27, 20, 100, 0.08); color: var(--navy); }
.stat-icon.sameday { background: rgba(255, 217, 48, 0.2); color: #B8960A; }
.stat-icon.free { background: rgba(16, 185, 129, 0.1); color: var(--green); }

.stat-number {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.2;
}

.stat-label {
  font-size: 0.82rem;
  color: var(--gray-400);
  font-weight: 500;
}

/* ============================================================
   SPECIALTIES
   ============================================================ */
.specialties {
  padding: 80px 0;
  background: var(--gray-50);
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.specialty-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  cursor: pointer;
  transition: all var(--transition);
}

.specialty-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--navy);
}

.specialty-card:hover .specialty-icon {
  background: var(--navy);
  color: var(--accent);
}

.specialty-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
  transition: all var(--transition);
}

.specialty-info h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.specialty-info p {
  font-size: 0.85rem;
  color: var(--gray-400);
  line-height: 1.4;
}

/* ============================================================
   HOW IT WORKS
   ============================================================ */
.how-it-works {
  padding: 80px 0;
}

.steps-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-row::before {
  content: '';
  position: absolute;
  top: 44px;
  left: calc(16.667% + 24px);
  right: calc(16.667% + 24px);
  height: 2px;
  background: var(--gray-200);
}

.step-card {
  text-align: center;
  padding: 0 16px;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--accent);
  font-size: 1.25rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  position: relative;
  z-index: 1;
}

.step-card h3 {
  margin-bottom: 12px;
  font-size: 1.1rem;
}

.step-card p {
  font-size: 0.92rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ============================================================
   TESTIMONIALS
   ============================================================ */
.testimonials {
  padding: 80px 0;
  background: var(--navy);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.testimonials::before {
  content: '';
  position: absolute;
  top: -100px;
  left: -100px;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 48, 0.08), transparent 70%);
  pointer-events: none;
}

.testimonials .section-label {
  color: var(--accent);
}

.testimonials .section-title {
  color: var(--white);
}

.testimonials .section-subtitle {
  color: rgba(255, 255, 255, 0.6);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: rgba(255, 255, 255, 0.07);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: transform var(--transition), background var(--transition);
}

.testimonial-card:hover {
  transform: translateY(-3px);
  background: rgba(255, 255, 255, 0.1);
}

.testimonial-stars {
  color: var(--accent);
  font-size: 0.9rem;
  letter-spacing: 2px;
  margin-bottom: 16px;
}

.testimonial-card blockquote {
  font-size: 0.95rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: rgba(255, 217, 48, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--accent);
}

.testimonial-name {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--white);
}

.testimonial-location {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.5);
}

/* ============================================================
   MOBILE APP PROMO
   ============================================================ */
.app-promo {
  padding: 80px 0;
}

.app-promo-inner {
  display: flex;
  align-items: center;
  gap: 64px;
  background: linear-gradient(135deg, var(--gray-50), #F0EDFF);
  border-radius: var(--radius-xl);
  padding: 64px;
  overflow: hidden;
}

.app-promo-content {
  flex: 1;
}

.app-promo-content h2 {
  margin-bottom: 16px;
}

.app-promo-content > p {
  font-size: 1.05rem;
  color: var(--gray-500);
  margin-bottom: 32px;
  line-height: 1.7;
}

.app-features {
  margin-bottom: 36px;
}

.app-features li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  font-size: 0.95rem;
  color: var(--gray-700);
}

.app-features li svg {
  width: 20px;
  height: 20px;
  color: var(--teal);
  flex-shrink: 0;
}

.app-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 24px;
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9rem;
  transition: background var(--transition), transform var(--transition);
}

.app-btn:hover {
  background: var(--navy-light);
  transform: translateY(-2px);
}

.app-btn svg {
  width: 22px;
  height: 22px;
}

.app-btn-text {
  text-align: left;
  line-height: 1.2;
}

.app-btn-label {
  font-size: 0.7rem;
  font-weight: 400;
  opacity: 0.7;
}

.app-btn-store {
  font-size: 1rem;
  font-weight: 700;
}

.app-promo-visual {
  flex: 0 0 280px;
  position: relative;
}

.phone-mockup {
  width: 240px;
  height: 480px;
  background: var(--navy);
  border-radius: 36px;
  padding: 12px;
  box-shadow: var(--shadow-xl);
  position: relative;
  margin: 0 auto;
}

.phone-screen {
  width: 100%;
  height: 100%;
  background: var(--white);
  border-radius: 26px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.phone-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--gray-500);
}

.phone-app-header {
  padding: 12px 16px;
  background: var(--navy);
  color: var(--white);
  font-weight: 700;
  font-size: 0.85rem;
}

.phone-app-content {
  padding: 16px;
  flex: 1;
}

.phone-search-mini {
  padding: 10px 12px;
  background: var(--gray-100);
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  color: var(--gray-400);
  margin-bottom: 16px;
}

.phone-card-mini {
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  padding: 12px;
  margin-bottom: 10px;
}

.phone-card-mini-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.phone-card-mini-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-200);
}

.phone-card-mini-name {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--navy);
}

.phone-card-mini-specialty {
  font-size: 0.6rem;
  color: var(--gray-400);
}

.phone-card-mini-bar {
  height: 6px;
  background: var(--gray-200);
  border-radius: 3px;
  margin-top: 6px;
}

.phone-card-mini-bar.short { width: 60%; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  padding: 64px 0 0;
  background: var(--gray-900);
  color: rgba(255, 255, 255, 0.7);
}

.footer-top {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-copy {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.35);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.5);
  transition: all var(--transition);
}

.footer-social a:hover {
  background: rgba(255, 255, 255, 0.15);
  color: var(--white);
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-top {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {
  .nav-desktop,
  .nav-actions {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .header-inner {
    height: 64px;
  }

  .hero {
    padding: 110px 0 60px;
  }

  .search-bar {
    flex-direction: column;
    align-items: stretch;
    padding: 8px;
  }

  .search-field:not(:last-of-type)::after {
    width: auto;
    height: 1px;
    top: auto;
    left: 16px;
    right: 16px;
    bottom: 0;
  }

  .search-btn {
    justify-content: center;
    margin-top: 4px;
  }

  .specialties-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .steps-row {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .steps-row::before {
    display: none;
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .app-promo-inner {
    flex-direction: column;
    padding: 40px 28px;
    gap: 40px;
    text-align: center;
  }

  .app-promo-visual {
    flex: none;
  }

  .app-features li {
    justify-content: center;
  }

  .app-buttons {
    justify-content: center;
  }

  .stat-card {
    padding: 14px 20px;
  }

  .stats-row {
    gap: 8px;
  }

  .footer-top {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .specialties-grid {
    grid-template-columns: 1fr;
  }

  .stats-row {
    flex-direction: column;
    align-items: stretch;
  }

  .footer-top {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .app-promo-inner {
    padding: 32px 20px;
  }

  .phone-mockup {
    width: 200px;
    height: 400px;
  }
}

/* ============================================================
   MedBook — Corporate Landing Page Styles
   ============================================================ */

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #1B1464;
  --navy-light: #2a1f8e;
  --accent: #FFD930;
  --accent-hover: #f0cb00;
  --white: #FFFFFF;
  --gray-50: #F8F9FC;
  --gray-100: #F0F2F7;
  --gray-200: #E2E5EE;
  --gray-300: #C8CDD9;
  --gray-400: #9BA3B5;
  --gray-500: #6B7280;
  --gray-700: #374151;
  --gray-900: #111827;
  --teal: #0EA5A0;
  --teal-light: #14C8C1;
  --blue: #0066FF;
  --green: #10B981;
  --shadow-sm: 0 1px 3px rgba(27, 20, 100, 0.06);
  --shadow-md: 0 4px 14px rgba(27, 20, 100, 0.08);
  --shadow-lg: 0 10px 30px rgba(27, 20, 100, 0.12);
  --shadow-xl: 0 20px 50px rgba(27, 20, 100, 0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: 0.2s ease;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-700);
  background: var(--white);
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition);
}

ul, ol { list-style: none; }

img { max-width: 100%; display: block; }

button, input, select {
  font-family: inherit;
  font-size: inherit;
  border: none;
  outline: none;
  background: none;
}

button { cursor: pointer; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Typography --- */
h1, h2, h3, h4 {
  color: var(--navy);
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.25rem); }
h3 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 12px;
}

.section-title {
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--gray-500);
  max-width: 600px;
  margin: 0 auto 48px;
}

.text-center { text-align: center; }

/* ============================================================
   HEADER
   ============================================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--navy);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.1rem;
  font-weight: 900;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-desktop a {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-500);
  transition: color var(--transition);
}

.nav-desktop a:hover {
  color: var(--navy);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-login {
  padding: 8px 20px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--navy);
  border-radius: var(--radius-full);
  transition: background var(--transition);
}

.btn-login:hover {
  background: var(--gray-100);
}

.btn-signup {
  padding: 8px 20px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--white);
  background: var(--navy);
  border-radius: var(--radius-full);
  transition: background var(--transition), transform var(--transition);
}

.btn-signup:hover {
  background: var(--navy-light);
  transform: translateY(-1px);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  cursor: pointer;
  z-index: 1100;
}

.hamburger span {
  display: block;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 0.3s ease;
  transform-origin: center;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7.5px) rotate(45deg);
}
.hamburger.active span:nth-child(2) {
  opacity: 0;
}
.hamburger.active span:nth-child(3) {
  transform: translateY(-7.5px) rotate(-45deg);
}

/* Mobile drawer */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 1050;
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
  transition: right 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-drawer.open {
  right: 0;
}

.mobile-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(27, 20, 100, 0.3);
  z-index: 1040;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-drawer-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-drawer a {
  display: block;
  padding: 16px 0;
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--navy);
  border-bottom: 1px solid var(--gray-100);
}

.mobile-drawer a:last-child {
  border-bottom: none;
}

.mobile-drawer .btn-signup-mobile {
  display: block;
  text-align: center;
  margin-top: 24px;
  padding: 14px;
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(170deg, #F0EDFF 0%, var(--white) 60%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -200px;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 48, 0.15), transparent 70%);
  pointer-events: none;
}

.hero-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(27, 20, 100, 0.06);
  padding: 6px 16px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 24px;
}

.hero-badge-dot {
  width: 8px;
  height: 8px;
  background: var(--green);
  border-radius: 50%;
  animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.3); }
}

.hero h1 {
  margin-bottom: 20px;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--navy), #4338CA);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--gray-500);
  max-width: 560px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

/* ============================================================
   SEARCH BAR
   ============================================================ */
.search-container {
  max-width: 820px;
  margin: 0 auto;
}

.search-bar {
  display: flex;
  align-items: center;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 2px solid var(--gray-200);
  padding: 6px;
  transition: border-color var(--transition), box-shadow var(--transition);
  position: relative;
}

.search-bar:focus-within {
  border-color: var(--navy);
  box-shadow: var(--shadow-xl), 0 0 0 4px rgba(27, 20, 100, 0.08);
}

.search-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  min-width: 0;
  position: relative;
}

.search-field:not(:last-of-type)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 8px;
  bottom: 8px;
  width: 1px;
  background: var(--gray-200);
}

.search-field svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--gray-400);
}

.search-field input,
.search-field select {
  width: 100%;
  padding: 4px 0;
  font-size: 0.95rem;
  color: var(--gray-900);
  background: transparent;
}

.search-field input::placeholder,
.search-field select {
  color: var(--gray-400);
}

.search-field select option {
  color: var(--gray-700);
}

.search-btn {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  background: var(--accent);
  color: var(--navy);
  font-weight: 700;
  font-size: 1rem;
  border-radius: var(--radius-md);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.search-btn:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(255, 217, 48, 0.4);
}

.search-btn svg {
  width: 18px;
  height: 18px;
}

/* Autocomplete dropdown */
.autocomplete-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  max-height: 320px;
  overflow-y: auto;
  z-index: 100;
  display: none;
}

.autocomplete-dropdown.active {
  display: block;
  animation: dropdown-in 0.2s ease;
}

@keyframes dropdown-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.autocomplete-group-label {
  padding: 12px 16px 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-400);
}

.autocomplete-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: background var(--transition);
}

.autocomplete-item:hover,
.autocomplete-item.highlighted {
  background: var(--gray-50);
}

.autocomplete-item-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.autocomplete-item-text strong {
  display: block;
  font-size: 0.95rem;
  color: var(--gray-900);
}

.autocomplete-item-text span {
  font-size: 0.82rem;
  color: var(--gray-400);
}

/* Search popular tags below bar */
.search-popular {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

.search-popular-label {
  font-size: 0.85rem;
  color: var(--gray-400);
  font-weight: 500;
}

.search-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  background: rgba(27, 20, 100, 0.05);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--navy);
  transition: background var(--transition);
  cursor: pointer;
}

.search-tag:hover {
  background: rgba(27, 20, 100, 0.1);
}

/* ============================================================
   PLATFORM STATS
   ============================================================ */
.stats {
  padding: 40px 0;
}

.stats-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 28px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: transform var(--transition), box-shadow var(--transition);
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.stat-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}

.stat-icon.reviews { background: rgba(14, 165, 160, 0.1); color: var(--teal); }
.stat-icon.providers { background: rgba(27, 20, 100, 0.08); color: var(--navy); }
.stat-icon.sameday { background: rgba(255, 217, 48, 0.2); color: #B8960A; }
.stat-icon.free { background: rgba(16, 185, 129, 0.1); color: var(--green); }

.stat-number {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.2;
}

.stat-label {
  font-size: 0.82rem;
  color: var(--gray-400);
  font-weight: 500;
}

/* ============================================================
   SPECIALTIES
   ============================================================ */
.specialties {
  padding: 80px 0;
  background: var(--gray-50);
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.specialty-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  cursor: pointer;
  transition: all var(--transition);
}

.specialty-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--navy);
}

.specialty-card:hover .specialty-icon {
  background: var(--navy);
  color: var(--accent);
}

.specialty-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
  transition: all var(--transition);
}

.specialty-info h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.specialty-info p {
  font-size: 0.85rem;
  color: var(--gray-400);
  line-height: 1.4;
}

/* ============================================================
   HOW IT WORKS
   ============================================================ */
.how-it-works {
  padding: 80px 0;
}

.steps-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-row::before {
  content: '';
  position: absolute;
  top: 44px;
  left: calc(16.667% + 24px);
  right: calc(16.667% + 24px);
  height: 2px;
  background: var(--gray-200);
}

.step-card {
  text-align: center;
  padding: 0 16px;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--accent);
  font-size: 1.25rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  position: relative;
  z-index: 1;
}

.step-card h3 {
  margin-bottom: 12px;
  font-size: 1.1rem;
}

.step-card p {
  font-size: 0.92rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ============================================================
   TESTIMONIALS
   ============================================================ */
.testimonials {
  padding: 80px 0;
  background: var(--navy);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.testimonials::before {
  content: '';
  position: absolute;
  top: -100px;
  left: -100px;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 48, 0.08), transparent 70%);
  pointer-events: none;
}

.testimonials .section-label {
  color: var(--accent);
}

.testimonials .section-title {
  color: var(--white);
}

.testimonials .section-subtitle {
  color: rgba(255, 255, 255, 0.6);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: rgba(255, 255, 255, 0.07);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: transform var(--transition), background var(--transition);
}

.testimonial-card:hover {
  transform: translateY(-3px);
  background: rgba(255, 255, 255, 0.1);
}

.testimonial-stars {
  color: var(--accent);
  font-size: 0.9rem;
  letter-spacing: 2px;
  margin-bottom: 16px;
}

.testimonial-card blockquote {
  font-size: 0.95rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: rgba(255, 217, 48, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--accent);
}

.testimonial-name {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--white);
}

.testimonial-location {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.5);
}

/* ============================================================
   MOBILE APP PROMO
   ============================================================ */
.app-promo {
  padding: 80px 0;
}

.app-promo-inner {
  display: flex;
  align-items: center;
  gap: 64px;
  background: linear-gradient(135deg, var(--gray-50), #F0EDFF);
  border-radius: var(--radius-xl);
  padding: 64px;
  overflow: hidden;
}

.app-promo-content {
  flex: 1;
}

.app-promo-content h2 {
  margin-bottom: 16px;
}

.app-promo-content > p {
  font-size: 1.05rem;
  color: var(--gray-500);
  margin-bottom: 32px;
  line-height: 1.7;
}

.app-features {
  margin-bottom: 36px;
}

.app-features li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  font-size: 0.95rem;
  color: var(--gray-700);
}

.app-features li svg {
  width: 20px;
  height: 20px;
  color: var(--teal);
  flex-shrink: 0;
}

.app-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 24px;
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9rem;
  transition: background var(--transition), transform var(--transition);
}

.app-btn:hover {
  background: var(--navy-light);
  transform: translateY(-2px);
}

.app-btn svg {
  width: 22px;
  height: 22px;
}

.app-btn-text {
  text-align: left;
  line-height: 1.2;
}

.app-btn-label {
  font-size: 0.7rem;
  font-weight: 400;
  opacity: 0.7;
}

.app-btn-store {
  font-size: 1rem;
  font-weight: 700;
}

.app-promo-visual {
  flex: 0 0 280px;
  position: relative;
}

.phone-mockup {
  width: 240px;
  height: 480px;
  background: var(--navy);
  border-radius: 36px;
  padding: 12px;
  box-shadow: var(--shadow-xl);
  position: relative;
  margin: 0 auto;
}

.phone-screen {
  width: 100%;
  height: 100%;
  background: var(--white);
  border-radius: 26px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.phone-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--gray-500);
}

.phone-app-header {
  padding: 12px 16px;
  background: var(--navy);
  color: var(--white);
  font-weight: 700;
  font-size: 0.85rem;
}

.phone-app-content {
  padding: 16px;
  flex: 1;
}

.phone-search-mini {
  padding: 10px 12px;
  background: var(--gray-100);
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  color: var(--gray-400);
  margin-bottom: 16px;
}

.phone-card-mini {
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  padding: 12px;
  margin-bottom: 10px;
}

.phone-card-mini-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.phone-card-mini-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-200);
}

.phone-card-mini-name {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--navy);
}

.phone-card-mini-specialty {
  font-size: 0.6rem;
  color: var(--gray-400);
}

.phone-card-mini-bar {
  height: 6px;
  background: var(--gray-200);
  border-radius: 3px;
  margin-top: 6px;
}

.phone-card-mini-bar.short { width: 60%; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  padding: 64px 0 0;
  background: var(--gray-900);
  color: rgba(255, 255, 255, 0.7);
}

.footer-top {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-copy {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.35);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.5);
  transition: all var(--transition);
}

.footer-social a:hover {
  background: rgba(255, 255, 255, 0.15);
  color: var(--white);
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-top {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {
  .nav-desktop,
  .nav-actions {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .header-inner {
    height: 64px;
  }

  .hero {
    padding: 110px 0 60px;
  }

  .search-bar {
    flex-direction: column;
    align-items: stretch;
    padding: 8px;
  }

  .search-field:not(:last-of-type)::after {
    width: auto;
    height: 1px;
    top: auto;
    left: 16px;
    right: 16px;
    bottom: 0;
  }

  .search-btn {
    justify-content: center;
    margin-top: 4px;
  }

  .specialties-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .steps-row {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .steps-row::before {
    display: none;
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .app-promo-inner {
    flex-direction: column;
    padding: 40px 28px;
    gap: 40px;
    text-align: center;
  }

  .app-promo-visual {
    flex: none;
  }

  .app-features li {
    justify-content: center;
  }

  .app-buttons {
    justify-content: center;
  }

  .stat-card {
    padding: 14px 20px;
  }

  .stats-row {
    gap: 8px;
  }

  .footer-top {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .specialties-grid {
    grid-template-columns: 1fr;
  }

  .stats-row {
    flex-direction: column;
    align-items: stretch;
  }

  .footer-top {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .app-promo-inner {
    padding: 32px 20px;
  }

  .phone-mockup {
    width: 200px;
    height: 400px;
  }
}

raw_arguments.content:
/* ============================================================
   MedBook — Corporate Landing Page Styles
   ============================================================ */

/* --- Reset & Base --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #1B1464;
  --navy-light: #2a1f8e;
  --accent: #FFD930;
  --accent-hover: #f0cb00;
  --white: #FFFFFF;
  --gray-50: #F8F9FC;
  --gray-100: #F0F2F7;
  --gray-200: #E2E5EE;
  --gray-300: #C8CDD9;
  --gray-400: #9BA3B5;
  --gray-500: #6B7280;
  --gray-700: #374151;
  --gray-900: #111827;
  --teal: #0EA5A0;
  --teal-light: #14C8C1;
  --blue: #0066FF;
  --green: #10B981;
  --shadow-sm: 0 1px 3px rgba(27, 20, 100, 0.06);
  --shadow-md: 0 4px 14px rgba(27, 20, 100, 0.08);
  --shadow-lg: 0 10px 30px rgba(27, 20, 100, 0.12);
  --shadow-xl: 0 20px 50px rgba(27, 20, 100, 0.15);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: 0.2s ease;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-700);
  background: var(--white);
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition);
}

ul, ol { list-style: none; }

img { max-width: 100%; display: block; }

button, input, select {
  font-family: inherit;
  font-size: inherit;
  border: none;
  outline: none;
  background: none;
}

button { cursor: pointer; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* --- Typography --- */
h1, h2, h3, h4 {
  color: var(--navy);
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.25rem); }
h3 { font-size: 1.25rem; }

.section-label {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--teal);
  margin-bottom: 12px;
}

.section-title {
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--gray-500);
  max-width: 600px;
  margin: 0 auto 48px;
}

.text-center { text-align: center; }

/* ============================================================
   HEADER
   ============================================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--navy);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--navy);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.1rem;
  font-weight: 900;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-desktop a {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--gray-500);
  transition: color var(--transition);
}

.nav-desktop a:hover {
  color: var(--navy);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-login {
  padding: 8px 20px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--navy);
  border-radius: var(--radius-full);
  transition: background var(--transition);
}

.btn-login:hover {
  background: var(--gray-100);
}

.btn-signup {
  padding: 8px 20px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--white);
  background: var(--navy);
  border-radius: var(--radius-full);
  transition: background var(--transition), transform var(--transition);
}

.btn-signup:hover {
  background: var(--navy-light);
  transform: translateY(-1px);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 28px;
  padding: 4px 0;
  cursor: pointer;
  z-index: 1100;
}

.hamburger span {
  display: block;
  height: 2.5px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 0.3s ease;
  transform-origin: center;
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7.5px) rotate(45deg);
}
.hamburger.active span:nth-child(2) {
  opacity: 0;
}
.hamburger.active span:nth-child(3) {
  transform: translateY(-7.5px) rotate(-45deg);
}

/* Mobile drawer */
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: 300px;
  max-width: 85vw;
  height: 100vh;
  background: var(--white);
  z-index: 1050;
  padding: 96px 32px 32px;
  box-shadow: var(--shadow-xl);
  transition: right 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.mobile-drawer.open {
  right: 0;
}

.mobile-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(27, 20, 100, 0.3);
  z-index: 1040;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.mobile-drawer-overlay.open {
  opacity: 1;
  pointer-events: all;
}

.mobile-drawer a {
  display: block;
  padding: 16px 0;
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--navy);
  border-bottom: 1px solid var(--gray-100);
}

.mobile-drawer a:last-child {
  border-bottom: none;
}

.mobile-drawer .btn-signup-mobile {
  display: block;
  text-align: center;
  margin-top: 24px;
  padding: 14px;
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  padding: 140px 0 80px;
  background: linear-gradient(170deg, #F0EDFF 0%, var(--white) 60%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -120px;
  right: -200px;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 48, 0.15), transparent 70%);
  pointer-events: none;
}

.hero-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(27, 20, 100, 0.06);
  padding: 6px 16px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 24px;
}

.hero-badge-dot {
  width: 8px;
  height: 8px;
  background: var(--green);
  border-radius: 50%;
  animation: pulse-dot 2s infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(1.3); }
}

.hero h1 {
  margin-bottom: 20px;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--navy), #4338CA);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--gray-500);
  max-width: 560px;
  margin: 0 auto 40px;
  line-height: 1.7;
}

/* ============================================================
   SEARCH BAR
   ============================================================ */
.search-container {
  max-width: 820px;
  margin: 0 auto;
}

.search-bar {
  display: flex;
  align-items: center;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  border: 2px solid var(--gray-200);
  padding: 6px;
  transition: border-color var(--transition), box-shadow var(--transition);
  position: relative;
}

.search-bar:focus-within {
  border-color: var(--navy);
  box-shadow: var(--shadow-xl), 0 0 0 4px rgba(27, 20, 100, 0.08);
}

.search-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  min-width: 0;
  position: relative;
}

.search-field:not(:last-of-type)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 8px;
  bottom: 8px;
  width: 1px;
  background: var(--gray-200);
}

.search-field svg {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--gray-400);
}

.search-field input,
.search-field select {
  width: 100%;
  padding: 4px 0;
  font-size: 0.95rem;
  color: var(--gray-900);
  background: transparent;
}

.search-field input::placeholder,
.search-field select {
  color: var(--gray-400);
}

.search-field select option {
  color: var(--gray-700);
}

.search-btn {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  background: var(--accent);
  color: var(--navy);
  font-weight: 700;
  font-size: 1rem;
  border-radius: var(--radius-md);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}

.search-btn:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(255, 217, 48, 0.4);
}

.search-btn svg {
  width: 18px;
  height: 18px;
}

/* Autocomplete dropdown */
.autocomplete-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  max-height: 320px;
  overflow-y: auto;
  z-index: 100;
  display: none;
}

.autocomplete-dropdown.active {
  display: block;
  animation: dropdown-in 0.2s ease;
}

@keyframes dropdown-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.autocomplete-group-label {
  padding: 12px 16px 6px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gray-400);
}

.autocomplete-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  transition: background var(--transition);
}

.autocomplete-item:hover,
.autocomplete-item.highlighted {
  background: var(--gray-50);
}

.autocomplete-item-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
}

.autocomplete-item-text strong {
  display: block;
  font-size: 0.95rem;
  color: var(--gray-900);
}

.autocomplete-item-text span {
  font-size: 0.82rem;
  color: var(--gray-400);
}

/* Search popular tags below bar */
.search-popular {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

.search-popular-label {
  font-size: 0.85rem;
  color: var(--gray-400);
  font-weight: 500;
}

.search-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  background: rgba(27, 20, 100, 0.05);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--navy);
  transition: background var(--transition);
  cursor: pointer;
}

.search-tag:hover {
  background: rgba(27, 20, 100, 0.1);
}

/* ============================================================
   PLATFORM STATS
   ============================================================ */
.stats {
  padding: 40px 0;
}

.stats-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 28px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  transition: transform var(--transition), box-shadow var(--transition);
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.stat-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}

.stat-icon.reviews { background: rgba(14, 165, 160, 0.1); color: var(--teal); }
.stat-icon.providers { background: rgba(27, 20, 100, 0.08); color: var(--navy); }
.stat-icon.sameday { background: rgba(255, 217, 48, 0.2); color: #B8960A; }
.stat-icon.free { background: rgba(16, 185, 129, 0.1); color: var(--green); }

.stat-number {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.2;
}

.stat-label {
  font-size: 0.82rem;
  color: var(--gray-400);
  font-weight: 500;
}

/* ============================================================
   SPECIALTIES
   ============================================================ */
.specialties {
  padding: 80px 0;
  background: var(--gray-50);
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.specialty-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px;
  background: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--gray-100);
  cursor: pointer;
  transition: all var(--transition);
}

.specialty-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--navy);
}

.specialty-card:hover .specialty-icon {
  background: var(--navy);
  color: var(--accent);
}

.specialty-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
  transition: all var(--transition);
}

.specialty-info h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.specialty-info p {
  font-size: 0.85rem;
  color: var(--gray-400);
  line-height: 1.4;
}

/* ============================================================
   HOW IT WORKS
   ============================================================ */
.how-it-works {
  padding: 80px 0;
}

.steps-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-row::before {
  content: '';
  position: absolute;
  top: 44px;
  left: calc(16.667% + 24px);
  right: calc(16.667% + 24px);
  height: 2px;
  background: var(--gray-200);
}

.step-card {
  text-align: center;
  padding: 0 16px;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--accent);
  font-size: 1.25rem;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  position: relative;
  z-index: 1;
}

.step-card h3 {
  margin-bottom: 12px;
  font-size: 1.1rem;
}

.step-card p {
  font-size: 0.92rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ============================================================
   TESTIMONIALS
   ============================================================ */
.testimonials {
  padding: 80px 0;
  background: var(--navy);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.testimonials::before {
  content: '';
  position: absolute;
  top: -100px;
  left: -100px;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 217, 48, 0.08), transparent 70%);
  pointer-events: none;
}

.testimonials .section-label {
  color: var(--accent);
}

.testimonials .section-title {
  color: var(--white);
}

.testimonials .section-subtitle {
  color: rgba(255, 255, 255, 0.6);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.testimonial-card {
  background: rgba(255, 255, 255, 0.07);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: transform var(--transition), background var(--transition);
}

.testimonial-card:hover {
  transform: translateY(-3px);
  background: rgba(255, 255, 255, 0.1);
}

.testimonial-stars {
  color: var(--accent);
  font-size: 0.9rem;
  letter-spacing: 2px;
  margin-bottom: 16px;
}

.testimonial-card blockquote {
  font-size: 0.95rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: rgba(255, 217, 48, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--accent);
}

.testimonial-name {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--white);
}

.testimonial-location {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.5);
}

/* ============================================================
   MOBILE APP PROMO
   ============================================================ */
.app-promo {
  padding: 80px 0;
}

.app-promo-inner {
  display: flex;
  align-items: center;
  gap: 64px;
  background: linear-gradient(135deg, var(--gray-50), #F0EDFF);
  border-radius: var(--radius-xl);
  padding: 64px;
  overflow: hidden;
}

.app-promo-content {
  flex: 1;
}

.app-promo-content h2 {
  margin-bottom: 16px;
}

.app-promo-content > p {
  font-size: 1.05rem;
  color: var(--gray-500);
  margin-bottom: 32px;
  line-height: 1.7;
}

.app-features {
  margin-bottom: 36px;
}

.app-features li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  font-size: 0.95rem;
  color: var(--gray-700);
}

.app-features li svg {
  width: 20px;
  height: 20px;
  color: var(--teal);
  flex-shrink: 0;
}

.app-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 24px;
  background: var(--navy);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.9rem;
  transition: background var(--transition), transform var(--transition);
}

.app-btn:hover {
  background: var(--navy-light);
  transform: translateY(-2px);
}

.app-btn svg {
  width: 22px;
  height: 22px;
}

.app-btn-text {
  text-align: left;
  line-height: 1.2;
}

.app-btn-label {
  font-size: 0.7rem;
  font-weight: 400;
  opacity: 0.7;
}

.app-btn-store {
  font-size: 1rem;
  font-weight: 700;
}

.app-promo-visual {
  flex: 0 0 280px;
  position: relative;
}

.phone-mockup {
  width: 240px;
  height: 480px;
  background: var(--navy);
  border-radius: 36px;
  padding: 12px;
  box-shadow: var(--shadow-xl);
  position: relative;
  margin: 0 auto;
}

.phone-screen {
  width: 100%;
  height: 100%;
  background: var(--white);
  border-radius: 26px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.phone-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--gray-500);
}

.phone-app-header {
  padding: 12px 16px;
  background: var(--navy);
  color: var(--white);
  font-weight: 700;
  font-size: 0.85rem;
}

.phone-app-content {
  padding: 16px;
  flex: 1;
}

.phone-search-mini {
  padding: 10px 12px;
  background: var(--gray-100);
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  color: var(--gray-400);
  margin-bottom: 16px;
}

.phone-card-mini {
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  padding: 12px;
  margin-bottom: 10px;
}

.phone-card-mini-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.phone-card-mini-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-200);
}

.phone-card-mini-name {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--navy);
}

.phone-card-mini-specialty {
  font-size: 0.6rem;
  color: var(--gray-400);
}

.phone-card-mini-bar {
  height: 6px;
  background: var(--gray-200);
  border-radius: 3px;
  margin-top: 6px;
}

.phone-card-mini-bar.short { width: 60%; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  padding: 64px 0 0;
  background: var(--gray-900);
  color: rgba(255, 255, 255, 0.7);
}

.footer-top {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
}

.footer-brand p {
  font-size: 0.9rem;
  line-height: 1.6;
  max-width: 280px;
}

.footer-col h4 {
  color: var(--white);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 5px 0;
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-copy {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.35);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.5);
  transition: all var(--transition);
}

.footer-social a:hover {
  background: rgba(255, 255, 255, 0.15);
  color: var(--white);
}

