   ============================================================ */
@media (max-width: 1024px) {
  .footer-top {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 768px) {
  .nav-desktop,
  .nav-actions {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .header-inner {
    height: 64px;
  }

  .hero {
    padding: 110px 0 60px;
  }

  .search-bar {
    flex-direction: column;
    align-items: stretch;
    padding: 8px;
  }

  .search-field:not(:last-of-type)::after {
    width: auto;
    height: 1px;
    top: auto;
    left: 16px;
    right: 16px;
    bottom: 0;
  }

  .search-btn {
    justify-content: center;
    margin-top: 4px;
  }

  .specialties-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .steps-row {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .steps-row::before {
    display: none;
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
  }

  .app-promo-inner {
    flex-direction: column;
    padding: 40px 28px;
    gap: 40px;
    text-align: center;
  }

  .app-promo-visual {
    flex: none;
  }

  .app-features li {
    justify-content: center;
  }

  .app-buttons {
    justify-content: center;
  }

  .stat-card {
    padding: 14px 20px;
  }

  .stats-row {
    gap: 8px;
  }

  .footer-top {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 16px;
  }

  .specialties-grid {
    grid-template-columns: 1fr;
  }

  .stats-row {
    flex-direction: column;
    align-items: stretch;
  }

  .footer-top {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .app-promo-inner {
    padding: 32px 20px;
  }

  .phone-mockup {
    width: 200px;
    height: 400px;
  }
}

